/**
 * One hit from the workspace file index.
 */
public struct SearchHit {
    public var path: String
    public var name: String
    public var score: Double
    public var context: String?
    public var lineNumber: UInt32?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(path: String, name: String, score: Double, context: String?, lineNumber: UInt32?) {
        self.path = path
        self.name = name
        self.score = score
        self.context = context
        self.lineNumber = lineNumber
    }
}



extension SearchHit: Equatable, Hashable {
    public static func ==(lhs: SearchHit, rhs: SearchHit) -> Bool {
        if lhs.path != rhs.path {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.score != rhs.score {
            return false
        }
        if lhs.context != rhs.context {
            return false
        }
        if lhs.lineNumber != rhs.lineNumber {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(path)
        hasher.combine(name)
        hasher.combine(score)
        hasher.combine(context)
        hasher.combine(lineNumber)
    }
}


