                lineNumber: FfiConverterOptionUInt32.read(from: &buf)
        )
    }

    public static func write(_ value: SearchHit, into buf: inout [UInt8]) {
        FfiConverterString.write(value.path, into: &buf)
        FfiConverterString.write(value.name, into: &buf)
        FfiConverterDouble.write(value.score, into: &buf)
        FfiConverterOptionString.write(value.context, into: &buf)
        FfiConverterOptionUInt32.write(value.lineNumber, into: &buf)
    }
}


