/**
 * A session, flattened for Swift. `Session::list` yields
 * `(String, DateTime<Utc>)`; `DateTime` has no UniFFI representation, so the
 * timestamp crosses as RFC3339 text and Swift parses it. Deliberate: an i64
 * epoch would silently lose the timezone the core carries.
 */
public struct SessionInfo {
    public var id: String
    public var updatedAtRfc3339: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, updatedAtRfc3339: String) {
        self.id = id
        self.updatedAtRfc3339 = updatedAtRfc3339
    }
}



extension SessionInfo: Equatable, Hashable {
    public static func ==(lhs: SessionInfo, rhs: SessionInfo) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.updatedAtRfc3339 != rhs.updatedAtRfc3339 {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(updatedAtRfc3339)
    }
}


